public Object dialog(DialogRunbase dialog = null, boolean forceOnClient = false)
{
    Dialog                 ret;

    ret = this.dialogInternal(dialog, forceOnClient);

    ret.caption("@GlobalUnifiedPricing:GUPPriceAttributeGroupHierarchyView");

    dfPriceComponentCodeName = ret.addField(extendedTypeStr(GUPPriceComponentCodeName),
                                            "@GlobalUnifiedPricing:GUPPriceComponentCode");

    dfPriceComponentCodeName.registerOverrideMethod(methodStr(FormStringControl, lookup), 
                                                    methodStr(GUPPriceAttributeGroupPriorityHierarchyView, lookupCodeName),
                                                    this);

    return ret;
}

protected void lookupCodeName(FormStringControl _ctrl)
{
    SysTableLookup          sysTableLookup;
    Query                   q = new Query();
    QueryBuildDataSource    qbds;

    sysTableLookup = SysTableLookup::newParameters(tableNum(GUPPriceComponentCode), _ctrl);
    sysTableLookup.addLookupfield(fieldNum(GUPPriceComponentCode, Name), true);
    sysTableLookup.addLookupfield(fieldNum(GUPPriceComponentCode, Description));

    qbds = q.addDataSource(tableNum(GUPPriceComponentCode));
    qbds.addRange(fieldNum(GUPPriceComponentCode, MaintenanceMode)).value(enum2Str(GUPPriceComponentCodeMaintenanceMode::Separate));

    sysTableLookup.parmQuery(q);
    sysTableLookup.performFormLookup();
}

public boolean validate(Object _calledFrom = null)
{
    boolean ret = super(_calledFrom);

    var priceComponentCodeName = dfPriceComponentCodeName.value();

    if (!GUPPriceComponentCode::findByName(dfPriceComponentCodeName.value()).RecId)
    {
        ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPPriceComponentCodeNotExist", priceComponentCodeName));
    }
    else if (GUPPriceComponentCode::findByName(dfPriceComponentCodeName.value()).MaintenanceMode != GUPPriceComponentCodeMaintenanceMode::Separate)
    {
        ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPPriceComponentCodeHierarchyViewNotAvailable", "@GlobalUnifiedPricing:GUPPriceComponentCodeCombinationMaintenanceMode_Joint"));
    }

    return ret;
}

public static void main(Args _args)
{
    var hierarchyView = GUPPriceAttributeGroupPriorityHierarchyView::construct();

    if (hierarchyView.prompt())
    {
        GUPPriceComponentCode rec = GUPPriceComponentCode::findByName(hierarchyView.dfPriceComponentCodeName.value());

        FormRun formRun = classfactory.formRunClass(new Args(formstr(GUPPriceAttributeGroupPriorityHierarchyView)));
        formRun.args().record(rec);
        formRun.run();
        formRun.wait();
    }

}
